/**
 * Bridge Types — interfaces for the Planner + Executor + Reasoner execution bridge.
 *
 * The bridge orchestrates step-by-step copilot execution with:
 * - ExecutionPlan: The plan generated by the Planner
 * - Step execution: Execute tool calls or evaluate conditions
 * - Reasoner decisions: Handle errors with retry, ask user, or abort
 * - Progress tracking: UI-friendly state for showing execution progress
 *
 * @module bridge/types
 */

// ─── Step Types ─────────────────────────────────────────────────────────────

/**
 * An execute step — calls a tool with parameters.
 */
export interface ExecuteStep {
  type: 'execute';
  /** Unique step identifier */
  id: string;
  /** Tool name to execute */
  tool: string;
  /** Parameters to pass to the tool */
  params: Record<string, unknown>;
  /** Human-readable label for UI */
  label: string;
}

/**
 * An evaluate step — evaluates a condition or makes a decision.
 */
export interface EvaluateStep {
  type: 'evaluate';
  /** Unique step identifier */
  id: string;
  /** Input reference (e.g., '$step1.result') */
  input: string;
  /** Decision question or condition to evaluate */
  decide: string;
  /** Human-readable label for UI */
  label: string;
}

/**
 * A step in the execution plan — either execute or evaluate.
 */
export type Step = ExecuteStep | EvaluateStep;

// ─── Plan Types ─────────────────────────────────────────────────────────────

/**
 * An execution plan generated by the Planner.
 */
export interface ExecutionPlan {
  /** The user's intent this plan addresses */
  intent: string;
  /** Ordered list of steps to execute */
  steps: Step[];
  /** Optional context data for the plan */
  context?: Record<string, unknown>;
}

// ─── Result Types ───────────────────────────────────────────────────────────

/**
 * Result of executing a step.
 */
export interface StepResult {
  /** ID of the step this result is for */
  stepId: string;
  /** Whether the step succeeded */
  success: boolean;
  /** Result data if successful */
  data?: unknown;
  /** Error message if failed */
  error?: string;
  /** Optional rollback function to undo this step */
  rollback?: () => void;
}

// ─── Reasoner Types ─────────────────────────────────────────────────────────

/**
 * Input provided to the Reasoner for error recovery decisions.
 */
export interface ReasonerInput {
  /** The step that failed */
  step: Step;
  /** The error encountered */
  error: string;
  /** Previous step results for context */
  previousResults: StepResult[];
  /** The full execution plan for context */
  plan: ExecutionPlan;
}

/**
 * Decision from the Reasoner on how to handle an error.
 */
export type ReasonerDecision =
  | { action: 'retry'; newParams: Record<string, unknown> }
  | { action: 'askUser'; question: string; options: string[] }
  | { action: 'abort'; reason: string }
  | { action: 'skip'; reason?: string }
  | { action: 'continue' };

// ─── UI Types ───────────────────────────────────────────────────────────────

/**
 * An expandable summary for showing step results.
 */
export interface ExpandableSummary {
  /** Short summary text */
  short: string;
  /** Detailed breakdown items */
  details: string[];
}

/**
 * Status of a step in the progress tracker.
 */
export type StepStatus = 'pending' | 'running' | 'done' | 'error' | 'skipped';

/**
 * A step in the progress state.
 */
export interface ProgressStep {
  /** Step ID */
  id: string;
  /** Human-readable label */
  label: string;
  /** Current status */
  status: StepStatus;
  /** Optional summary when done */
  summary?: ExpandableSummary;
  /** Optional error message */
  error?: string;
}

/**
 * Overall progress state for the UI.
 */
export interface ProgressState {
  /** Overall execution status */
  status: 'idle' | 'running' | 'paused' | 'done' | 'error';
  /** The intent being executed */
  intent: string;
  /** List of steps with their status */
  steps: ProgressStep[];
  /** Index of the currently executing step */
  currentStepIndex: number;
  /** Final result summary when done */
  finalSummary?: ExpandableSummary;
  /** Error message if execution failed */
  error?: string;
}

// ─── Event Types ────────────────────────────────────────────────────────────

/**
 * Events emitted during bridge execution.
 */
export type BridgeEvent =
  | { type: 'plan:start'; plan: ExecutionPlan }
  | { type: 'plan:complete'; results: StepResult[] }
  | { type: 'plan:error'; error: string }
  | { type: 'step:start'; step: Step; index: number }
  | { type: 'step:complete'; step: Step; result: StepResult }
  | { type: 'step:error'; step: Step; error: string }
  | { type: 'reasoner:invoke'; input: ReasonerInput }
  | { type: 'reasoner:decision'; decision: ReasonerDecision }
  | { type: 'user:prompt'; question: string; options: string[] }
  | { type: 'user:response'; response: string }
  | { type: 'progress:update'; state: ProgressState };

/**
 * Handler for bridge events.
 */
export type BridgeEventHandler = (event: BridgeEvent) => void;

// ─── Configuration ──────────────────────────────────────────────────────────

/**
 * Configuration for the execution bridge.
 */
export interface BridgeConfig {
  /** Maximum number of retries per step */
  maxRetries: number;
  /** Timeout per step in milliseconds */
  stepTimeout: number;
  /** Whether to enable automatic rollback on failure */
  enableRollback: boolean;
  /** Whether to pause execution for user confirmation at each step */
  requireConfirmation: boolean;
  /** Whether to enable verbose logging */
  verbose: boolean;
}

/**
 * Default bridge configuration.
 */
export const DEFAULT_BRIDGE_CONFIG: BridgeConfig = {
  maxRetries: 3,
  stepTimeout: 30000,
  enableRollback: true,
  requireConfirmation: false,
  verbose: false,
};

// ─── Type Guards ────────────────────────────────────────────────────────────

/**
 * Type guard to check if a step is an ExecuteStep.
 */
export function isExecuteStep(step: Step): step is ExecuteStep {
  return step.type === 'execute';
}

/**
 * Type guard to check if a step is an EvaluateStep.
 */
export function isEvaluateStep(step: Step): step is EvaluateStep {
  return step.type === 'evaluate';
}
